// The /licenses/ notices are generated by the production build. These tests run the same
// generator against the committed data (it must be complete today) and against small
// synthetic trees that each break one thing, so a missing licence is shown to fail it.
import { afterEach, describe, expect, it } from 'vitest'
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { dirname, join } from 'node:path'
import { buildNotices, collectEngines, collectNpm, declaredLicense, spdxIds } from './notices'

const ROOT = join(__dirname, '..', '..')
const roots: string[] = []
afterEach(() => {
  while (roots.length) rmSync(roots.pop()!, { recursive: true, force: true })
})

function tree(files: Record<string, string>): string {
  const root = mkdtempSync(join(tmpdir(), 'notices-'))
  roots.push(root)
  for (const [rel, data] of Object.entries(files)) {
    mkdirSync(dirname(join(root, rel)), { recursive: true })
    writeFileSync(join(root, rel), data)
  }
  return root
}

const NPM_CFG = JSON.stringify({
  servedCopies: {},
  upstreamTexts: {},
  elections: { dual: { use: 'MIT', offered: 'MIT OR GPL-3.0-or-later' } },
  otherServedFiles: [],
})
const MIT = readFileSync(join(ROOT, 'src/data/licenses/texts/spdx/MIT.txt'), 'utf8')

describe('licence notices — helpers', () => {
  it('reads every package.json licence shape', () => {
    expect(declaredLicense({ license: 'MIT' })).toBe('MIT')
    expect(declaredLicense({ license: { type: 'ISC' } })).toBe('ISC')
    expect(declaredLicense({ licenses: [{ type: 'MIT' }, { type: 'Apache-2.0' }] })).toBe(
      'MIT OR Apache-2.0'
    )
    expect(declaredLicense({})).toBeUndefined()
    expect(spdxIds('(MIT OR Apache-2.0)')).toEqual(['MIT', 'Apache-2.0'])
  })
})

describe('licence notices — npm packages', () => {
  it('copies the licence files a package ships', () => {
    const root = tree({
      'src/data/licenses/npmNotices.json': NPM_CFG,
      'node_modules/a/package.json': JSON.stringify({
        name: 'a',
        version: '1.0.0',
        license: 'MIT',
      }),
      'node_modules/a/LICENSE': 'Copyright (c) A Author\nMIT body',
    })
    const { entries, problems } = collectNpm(root, ['node_modules/a'])
    expect(problems).toEqual([])
    expect(entries[0].files).toEqual([
      { name: 'LICENSE', text: 'Copyright (c) A Author\nMIT body' },
    ])
  })

  it('falls back to the standard text naming the author, honouring a recorded licence choice', () => {
    const root = tree({
      'src/data/licenses/npmNotices.json': NPM_CFG,
      'src/data/licenses/texts/spdx/MIT.txt': MIT,
      'node_modules/dual/package.json': JSON.stringify({
        name: 'dual',
        version: '2.0.0',
        license: '(MIT OR GPL-3.0-or-later)',
        author: 'Dee Author <dee@example.org>',
      }),
    })
    const { entries, problems } = collectNpm(root, ['node_modules/dual'])
    expect(problems).toEqual([])
    expect(entries[0].files).toHaveLength(1)
    expect(entries[0].files[0].text).toContain('Copyright (c) Dee Author')
    expect(entries[0].files[0].text).not.toContain('dee@example.org')
  })

  it('SABOTAGE: a shipped package with no licence at all fails', () => {
    const root = tree({
      'src/data/licenses/npmNotices.json': NPM_CFG,
      'node_modules/bare/package.json': JSON.stringify({ name: 'bare', version: '0.1.0' }),
    })
    expect(collectNpm(root, ['node_modules/bare']).problems.join('\n')).toMatch(
      /bare@0\.1\.0: shipped with no declared licence and no licence file/
    )
  })

  it('SABOTAGE: no file and no standard text for the declared licence fails', () => {
    const root = tree({
      'src/data/licenses/npmNotices.json': NPM_CFG,
      'node_modules/odd/package.json': JSON.stringify({
        name: 'odd',
        version: '1.0.0',
        license: 'WTFPL',
      }),
    })
    expect(collectNpm(root, ['node_modules/odd']).problems.join('\n')).toMatch(
      /no standard text for "WTFPL"/
    )
  })
})

describe('licence notices — engines', () => {
  it('SABOTAGE: a served engine bundle with no notices entry fails', () => {
    const root = tree({
      'src/data/licenses/engineNotices.json': JSON.stringify({
        textSources: {},
        toolchains: {},
        bundles: [],
      }),
      'src/data/licenses/crateLicenseTexts.json': JSON.stringify({
        commit: 'x',
        crates: {},
        texts: {},
      }),
      'src/data/sbomRustLock.json': JSON.stringify({ forks: {}, unscannable: {} }),
      'public/wasm/wasm-provenance.json': JSON.stringify({
        hsmRepo: 'o/r',
        bundles: [{ name: 'new-engine', files: ['public/wasm/new.wasm'], hsmCommit: null }],
      }),
      'src/data/sbomWasmArtifacts.json': JSON.stringify({ artifacts: [] }),
    })
    expect(collectEngines(root).problems.join('\n')).toMatch(
      /engine bundle "new-engine" is served but has no entry/
    )
  })
})

describe('licence notices — the committed data is complete', () => {
  const keys = (
    JSON.parse(readFileSync(join(ROOT, 'src/data/sbomBundledPackages.json'), 'utf8')) as {
      packages: string[]
    }
  ).packages
  const { files, problems } = buildNotices(ROOT, keys, {
    version: '0.0.0-test',
    commit: '0123456789abcdef0123456789abcdef01234567',
  })

  it('has no missing licence, text or engine entry', () => {
    expect(problems).toEqual([])
  })

  it('writes a notices file for every served engine bundle', () => {
    const prov = JSON.parse(
      readFileSync(join(ROOT, 'public/wasm/wasm-provenance.json'), 'utf8')
    ) as { bundles: { name: string }[] }
    const arts = JSON.parse(
      readFileSync(join(ROOT, 'src/data/sbomWasmArtifacts.json'), 'utf8')
    ) as { artifacts: { key: string }[] }
    for (const key of [...prov.bundles.map((b) => b.name), ...arts.artifacts.map((a) => a.key)])
      expect(files[`licenses/engines/${key}.txt`], key).toBeTruthy()
  })

  it('carries strongSwan’s GPL text and the source of the served build', () => {
    const s = files['licenses/engines/strongswan.txt']
    expect(s).toContain('GNU GENERAL PUBLIC LICENSE')
    expect(s).toContain('GPL-2.0-or-later')
    expect(s).toContain('bf53023b78b42078b5936dab91809eaeb9f756e3')
    expect(s).toContain('strongswan-6.0.5.tar.bz2')
  })

  it('lists the Rust crates found in the engine binary with their licence files', () => {
    const s = files['licenses/engines/softhsmrustv3-engine.txt']
    expect(s).toMatch(/sha2@\d+\.\d+\.\d+ - /)
    expect(s).toContain('fips204@0.4.6')
    expect(s).toContain('modified by PQC Today')
  })

  it('includes the licence files of bundled npm packages, and links the exact source', () => {
    expect(files['licenses/npm-packages.txt']).toMatch(/^react \d+\.\d+\.\d+ - MIT$/m)
    expect(files['licenses/index.html']).toContain(
      'https://github.com/pqctoday-org/pqctoday-hub/tree/0123456789abcdef0123456789abcdef01234567'
    )
  })

  it('names no personal machine path', () => {
    for (const [f, s] of Object.entries(files)) expect(s, f).not.toMatch(/\/Users\/[a-z]/)
  })
})
